'use client';

import { useEffect, useRef, useState } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import * as THREE from 'three';
import { FishManager, FishConfig } from '@/utils/FishManager';
import Substrate from '@/components/Substrate';
import PlantField from '@/components/PlantField';
import { supabase } from '@/lib/supabaseClient';

// Akvaryum Boyutları
const TANK_BOUNDS = new THREE.Vector3(14, 7, 7);

// Supabase'den veya Fallback'ten Balık Konfigürasyonlarını Çeken Metot
async function fetchFishConfigsFromSupabase(): Promise<FishConfig[]> {
  try {
    const { data, error } = await supabase
      .from('fish_species')
      .select('*');

    if (error || !data || data.length === 0) {
      console.warn('Supabase verisi alınamadı, varsayılan Vatoz konfigürasyonu kullanılıyor.', error);
      // Fallback: Renk ayarı tamamen config üzerinden (Bej tonu: #d4c2a0)
      return [
        {
          id: 'pleco',
          name: 'Vatoz',
          modelPath: '/models/pleco.glb',
          behavior: 'bottom_dweller',
          appearance: {
            color: '#d4c2a0', // Doğal bej rengi config'den çekiliyor
            roughness: 0.4,
            metalness: 0.1
          },
          physics: {
            minSpeed: 0.008,
            maxSpeed: 0.02,
            diveInterval: 250,
            verticalFreedom: 0.0,
            turnSpeed: 0.035,
          },
          swimShader: {
            bodySpeed: 1.8,
            bodyFreq: 2.2,
            bodyAmp: 0.012,
            finSpeed: 4.5,
            pectoralAmp: 0.025,
            caudalWhip: 0.035,
          },
        },
      ];
    }

    return data.map((item) => ({
      id: item.id,
      name: item.name,
      modelPath: item.model_path,
      behavior: item.behavior,
      appearance: {
        color: item.color ?? '#d4c2a0',
        roughness: item.roughness ?? 0.4,
        metalness: item.metalness ?? 0.1,
      },
      physics: {
        minSpeed: item.min_speed ?? 0.01,
        maxSpeed: item.max_speed ?? 0.025,
        diveInterval: item.dive_interval ?? 200,
        verticalFreedom: item.vertical_freedom ?? 0.0,
        turnSpeed: item.turn_speed ?? 0.035,
      },
      swimShader: {
        bodySpeed: item.body_speed ?? 1.8,
        bodyFreq: item.body_freq ?? 2.2,
        bodyAmp: item.body_amp ?? 0.012,
        finSpeed: item.fin_speed ?? 4.5,
        pectoralAmp: item.pectoral_amp ?? 0.025,
        caudalWhip: item.caudal_whip ?? 0.035,
      },
    }));
  } catch (err) {
    console.error('Supabase bağlantı hatası:', err);
    return [];
  }
}

function SimulationController({
  fishCount,
  fishConfigs,
  onFpsUpdate,
}: {
  fishCount: number;
  fishConfigs: FishConfig[];
  onFpsUpdate: (fps: number) => void;
}) {
  const { scene } = useThree();
  const fishManagerRef = useRef<FishManager | null>(null);

  const frameCountRef = useRef(0);
  const lastFpsUpdateRef = useRef(performance.now());
  const startTimeRef = useRef(performance.now());

  useEffect(() => {
    if (fishConfigs.length > 0) {
      if (!fishManagerRef.current) {
        fishManagerRef.current = new FishManager(scene, TANK_BOUNDS, fishCount, fishConfigs);
      } else {
        fishManagerRef.current.updateConfigs(fishConfigs);
      }
    }
  }, [scene, fishConfigs]);

  useEffect(() => {
    if (fishManagerRef.current) {
      fishManagerRef.current.setFishCount(fishCount);
    }
  }, [fishCount]);

  useFrame(() => {
    const elapsedTime = (performance.now() - startTimeRef.current) * 0.001;

    if (fishManagerRef.current) {
      fishManagerRef.current.update(elapsedTime);
    }

    frameCountRef.current++;
    const now = performance.now();
    if (now - lastFpsUpdateRef.current >= 500) {
      const currentFps = Math.round((frameCountRef.current * 1000) / (now - lastFpsUpdateRef.current));
      onFpsUpdate(currentFps);
      frameCountRef.current = 0;
      lastFpsUpdateRef.current = now;
    }
  });

  return null;
}

function GlassBounds() {
  return (
    <lineSegments position={[0, 0, 0]}>
      <edgesGeometry args={[new THREE.BoxGeometry(TANK_BOUNDS.x, TANK_BOUNDS.y, TANK_BOUNDS.z)]} />
      <lineBasicMaterial color="#38bdf8" transparent opacity={0.35} />
    </lineSegments>
  );
}

export default function AquariumScene() {
  const [fishCount, setFishCount] = useState<number>(20);
  const [fps, setFps] = useState<number>(60);
  const [fishConfigs, setFishConfigs] = useState<FishConfig[]>([]);

  useEffect(() => {
    async function loadConfigs() {
      const configs = await fetchFishConfigsFromSupabase();
      setFishConfigs(configs);
    }
    loadConfigs();
  }, []);

  return (
    <div style={{ width: '100vw', height: '100vh', position: 'relative', overflow: 'hidden', backgroundColor: '#04192b' }}>
      
      {/* Sağ Üst: Şık Cam Efektli UI Kontrol Paneli */}
      <div
        style={{
          position: 'absolute',
          top: '20px',
          right: '20px',
          zIndex: 50,
          background: 'rgba(4, 25, 43, 0.85)',
          backdropFilter: 'blur(10px)',
          WebkitBackdropFilter: 'blur(10px)',
          border: '1px solid rgba(56, 189, 248, 0.35)',
          borderRadius: '14px',
          padding: '16px 20px',
          color: '#e2f1fd',
          display: 'flex',
          flexDirection: 'column',
          gap: '14px',
          minWidth: '220px',
          boxShadow: '0 8px 32px rgba(0, 0, 0, 0.5)',
          fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
        }}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid rgba(56, 189, 248, 0.2)', paddingBottom: '8px' }}>
          <span style={{ fontSize: '11px', fontWeight: 700, letterSpacing: '1px', color: '#38bdf8', textTransform: 'uppercase' }}>
            Akvaryum Kontrol
          </span>
          <span style={{ fontSize: '10px', color: '#94a3b8', fontFamily: 'monospace' }}>Config Engine</span>
        </div>

        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '13px', fontWeight: 500 }}>
          <span style={{ color: '#cbd5e1' }}>Performans</span>
          <span style={{ color: '#38bdf8', fontWeight: 700, fontFamily: 'monospace', fontSize: '15px' }}>
            {fps} <span style={{ fontSize: '11px', fontWeight: 400, color: '#94a3b8' }}>FPS</span>
          </span>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '13px', fontWeight: 500 }}>
            <span style={{ color: '#cbd5e1' }}>Balık Popülasyonu</span>
            <span style={{ color: '#38bdf8', fontWeight: 700, fontFamily: 'monospace', fontSize: '15px' }}>{fishCount}</span>
          </div>
          <input
            type="range"
            min="1"
            max="100"
            value={fishCount}
            onChange={(e) => setFishCount(parseInt(e.target.value, 10))}
            style={{
              width: '100%',
              height: '6px',
              borderRadius: '4px',
              outline: 'none',
              cursor: 'pointer',
              accentColor: '#38bdf8'
            }}
          />
        </div>
      </div>

      <Canvas
        camera={{ position: [0, 0, 7.5], fov: 55 }}
        onCreated={({ scene }) => {
          scene.background = new THREE.Color(0x04192b);
          scene.fog = new THREE.FogExp2(0x04192b, 0.045);
        }}
      >
        <directionalLight position={[0, 8, 2]} intensity={2.2} color="#dcf4ff" />
        <ambientLight intensity={1.4} color="#0a3c59" />

        <GlassBounds />
        <Substrate tankBounds={TANK_BOUNDS} />
        <PlantField tankBounds={TANK_BOUNDS} />

        <SimulationController
          fishCount={fishCount}
          fishConfigs={fishConfigs}
          onFpsUpdate={setFps}
        />

        <OrbitControls makeDefault enableDamping dampingFactor={0.05} minDistance={3} maxDistance={20} />
      </Canvas>
    </div>
  );
}