// src/components/PlantField.tsx

'use client';

import { useMemo, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { CustomShader } from '@/utils/FishManager';

interface PlantFieldProps {
  tankBounds: THREE.Vector3;
  count?: number;
}

// Fonksiyonu normal tanımlayıp en altta default export ediyoruz
function PlantField({ tankBounds, count = 100 }: PlantFieldProps) {
  const meshRef = useRef<THREE.InstancedMesh>(null);
  const shaderRef = useRef<CustomShader | null>(null);

  // 1. Geometri Tanımı ve Kök Hizalama
  const leafGeom = useMemo(() => {
    const geom = new THREE.PlaneGeometry(0.18, 2.5, 4, 16);
    geom.translate(0, 1.25, 0);
    return geom;
  }, []);

  // 2. Vertex Shader Salınım Materyali
  const material = useMemo(() => {
    const mat = new THREE.MeshStandardMaterial({
      color: 0x1f7a42,
      roughness: 0.8,
      side: THREE.DoubleSide,
    });

    mat.onBeforeCompile = (shader: CustomShader) => {
      shader.uniforms.uTime = { value: 0 };
      shaderRef.current = shader;

      shader.vertexShader = `
        uniform float uTime;
        ${shader.vertexShader}
      `;

      shader.vertexShader = shader.vertexShader.replace(
        '#include <begin_vertex>',
        `
        #include <begin_vertex>
        float swayFactor = smoothstep(0.0, 2.5, position.y);
        float current = sin(uTime * 1.8 + position.y * 1.2 + modelMatrix[3][0]) * 0.28;
        transformed.x += current * swayFactor;
        transformed.z += cos(uTime * 1.2 + position.y * 0.9) * 0.15 * swayFactor;
        `
      );
    };

    return mat;
  }, []);

  // 3. Matris Hesabı (Rastgele Pozisyon, Rotasyon ve Ölçek)
  const matrices = useMemo(() => {
    const tempMatrices: THREE.Matrix4[] = [];
    const dummy = new THREE.Object3D();
    const bottomY = -tankBounds.y / 2 + 0.1;

    for (let i = 0; i < count; i++) {
      dummy.position.set(
        (Math.random() - 0.5) * (tankBounds.x - 1.5),
        bottomY,
        (Math.random() - 0.5) * (tankBounds.z - 1.5)
      );
      dummy.rotation.y = Math.random() * Math.PI;
      const scaleY = 0.7 + Math.random() * 0.6;
      dummy.scale.set(1, scaleY, 1);
      dummy.updateMatrix();

      tempMatrices.push(dummy.matrix.clone());
    }
    return tempMatrices;
  }, [tankBounds, count]);

  // 4. Her Render Karesinde Shader Zaman Güncellemesi
  useFrame((state) => {
    if (shaderRef.current) {
      shaderRef.current.uniforms.uTime.value = state.clock.getElapsedTime();
    }
  });

  return (
    <instancedMesh
      ref={meshRef}
      args={[leafGeom, material, count]}
      onUpdate={(self) => {
        matrices.forEach((mat, i) => {
          self.setMatrixAt(i, mat);
        });
        self.instanceMatrix.needsUpdate = true;
      }}
    />
  );
}

// Kesin Default Export Tanımı
export default PlantField;